<?php require dirname(__DIR__).'/app/bootstrap.php';if(PHP_SAPI!=='cli')exit("CLI only\n");$d=db();$d->exec("UPDATE jobs SET status='queued',available_at=NOW(),updated_at=NOW(),error_message='Recovered stale worker lease' WHERE status='processing' AND updated_at < NOW() - INTERVAL 20 MINUTE AND attempts < 3");$d->exec("UPDATE transcripts t JOIN jobs j ON j.transcript_id=t.id SET t.status='queued',t.updated_at=NOW() WHERE j.status='queued' AND t.status='processing'");$limit=max(1,min(50,(int)($argv[1]??5)));$done=0;for($i=0;$i<$limit;$i++){$d=db();$d->beginTransaction();try{$s=$d->query("SELECT * FROM jobs WHERE status='queued' AND available_at<=NOW() ORDER BY id LIMIT 1 FOR UPDATE");$j=$s->fetch();if(!$j){$d->commit();break;}$d->prepare("UPDATE jobs SET status='processing',attempts=attempts+1,started_at=NOW(),updated_at=NOW() WHERE id=?")->execute([$j['id']]);$d->commit();}catch(Throwable $e){$d->rollBack();throw $e;}TranscriptService::process($j);$done++;echo "Processed job ".$j['id'].PHP_EOL;}echo "Done: ".$done.PHP_EOL;
